    ending: "God gives you a hard message about Eli's household, and over time you become a prophet and judge of Israel, God's voice for an entire nation for decades.",
    reflection: "Samuel's calling came at night, in repeated whispers, and required a boy to learn to recognize a voice he didn't yet know.",
