    ending: "Daniel interprets the message: 'Mene, Mene, Tekel, Parsin' — your kingdom has been weighed and found wanting, and will be given to the Medes and Persians. That very night, Belshazzar dies and the kingdom falls.",
    reflection: "Belshazzar used sacred objects for his own glory at a party, never imagining that same night would be the last of his reign.",
